-- Backfill every currently live hand-built quiz page into the CMS model.
-- Artwork is stored as a bucket-relative object path. The API expands it with
-- the active environment's Supabase URL, so staging and production use their
-- own CDN without environment-specific data in this migration.

CREATE TEMP TABLE quiz_page_content_seed (
  slug TEXT PRIMARY KEY,
  internal_name TEXT NOT NULL,
  page_category TEXT NOT NULL,
  h1 TEXT NOT NULL,
  lede TEXT NOT NULL,
  about_heading TEXT NOT NULL,
  about_blocks JSONB NOT NULL,
  score_cta TEXT NOT NULL,
  footer_banner_text TEXT NOT NULL,
  footer_button_label TEXT NOT NULL,
  hero_image_file TEXT NOT NULL,
  hero_image_alt TEXT NOT NULL,
  seo_title TEXT NOT NULL,
  meta_description TEXT NOT NULL,
  breadcrumb_label TEXT NOT NULL
);

INSERT INTO quiz_page_content_seed VALUES
  ('liverpool', 'Liverpool Quiz', 'team', 'Liverpool Quiz — Test Your LFC Knowledge', 'Think you know the Reds? Play our free Liverpool quiz — {count} verified questions covering Anfield legends, European nights and Premier League glory. No sign-up needed: answer, get your score instantly, and see how you rank against thousands of football fans. Ready when you are — kick off below.', 'About this Liverpool football quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Few clubs pack as much history into a quiz as Liverpool FC. This Liverpool football quiz draws on more than a century of drama at Anfield — from Bill Shankly rebuilding the club in the 1960s to the miracle of Istanbul in 2005, when the Reds came back from three goals down against AC Milan to lift a fifth European Cup."},{"id":"paragraph-2","type":"paragraph","text":"Our questions are pulled from QuizBall’s bank of verified football trivia, so every answer has been checked. Expect the icons — Ian Rush’s goalscoring records, King Kenny Dalglish, Steven Gerrard’s leadership — alongside modern history: Jürgen Klopp’s Champions League win in 2019 and the long-awaited league title that followed a year later."},{"id":"paragraph-3","type":"paragraph","text":"Whether you stand on the Kop every other week or just want a proper test of your ball knowledge, take the quiz on Liverpool above and see your score instantly. Fancy a bigger challenge? QuizBall’s wider question bank can also be played head-to-head — sign up free and defend your score against real opponents in live trivia duels."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Think you know the Reds? Prove it against real fans — play ranked football trivia duels on QuizBall.', 'Play Ranked', 'liverpool-v2.webp', 'Liverpool FC category artwork', 'Liverpool Quiz — Test Your LFC Knowledge | QuizBall', 'Free Liverpool quiz — {count} verified questions on the Reds. Instant score, no sign-up needed to play. Then take on real fans in ranked football duels.', 'Liverpool Quiz'),
  ('manchester-united', 'Man United Quiz', 'team', 'Man United Quiz — Test Your Red Devils Knowledge', 'How well do you really know Manchester United? Play our free Man United quiz — {count} verified questions on Old Trafford legends, treble glory and Premier League dominance. No sign-up needed: instant score, then see how you compare with thousands of football fans. Kick off below.', 'About this Manchester United quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Manchester United’s story reads like a script: the Busby Babes and the tragedy of Munich in 1958, redemption at Wembley in 1968 as the first English winners of the European Cup, and the Ferguson era that turned the Premier League into a red procession — 13 titles, the 1999 treble, and that injury-time night at the Camp Nou."},{"id":"paragraph-2","type":"paragraph","text":"This Man United quiz pulls {count} verified questions from QuizBall’s football trivia bank, covering the icons — Sir Bobby Charlton, Eric Cantona, the Class of 92, Wayne Rooney’s record-breaking goals — plus the moments every United fan argues about at the pub. Every answer has been checked before it reaches you."},{"id":"paragraph-3","type":"paragraph","text":"Play the manchester united quiz above for free, get your score instantly, and replay for a fresh set of questions. And when a solo score isn’t enough, do what United sides always did: take it to a bigger stage. Sign up free and play ranked head-to-head duels against real fans, where every correct answer is a shot on goal."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Fancy yourself a proper Red? Prove it in live trivia duels against real fans.', 'Play Ranked', 'manchester-united-v2.webp', 'Manchester United category artwork', 'Man United Quiz — Test Your Red Devils Knowledge | QuizBall', 'Free Man United quiz — {count} verified questions on the Red Devils. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Man United Quiz'),
  ('tottenham', 'Tottenham Quiz', 'team', 'Tottenham Quiz — Test Your Spurs Knowledge', 'Audere est facere — to dare is to do. Dare to take our free Tottenham quiz: {count} verified questions on Spurs legends, White Hart Lane history and famous European nights. No sign-up needed — instant score, then see how you compare with thousands of football fans.', 'About this Tottenham Hotspur quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Tottenham Hotspur have always done things with style — it’s written into the club motto. This tottenham hotspur quiz covers the lot: Bill Nicholson’s 1961 double winners, the first English club to achieve the feat in the 20th century; Jimmy Greaves banging in goals at White Hart Lane; Gareth Bale terrorising full-backs before his world-record move to Real Madrid; and Harry Kane rewriting the club’s scoring records on his way to becoming England’s record goalscorer."},{"id":"paragraph-2","type":"paragraph","text":"Every question comes from QuizBall’s verified trivia bank, so the facts stand up to pub-argument scrutiny. You’ll get {count} questions per round — five easy, five medium and five hard."},{"id":"paragraph-3","type":"paragraph","text":"Play the spurs quiz above for free and get your score instantly, no account needed. Then, if you’re feeling daring, do what the motto demands: sign up free and take your ball knowledge into live ranked duels against real opponents, where every correct answer brings you closer to goal."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'To dare is to do — take your Spurs knowledge into live duels against real fans.', 'Play Ranked', 'tottenham-v2.webp', 'Tottenham Hotspur category artwork', 'Tottenham Quiz — Test Your Spurs Knowledge | QuizBall', 'Free Tottenham quiz — {count} verified questions on Spurs. Instant score, no sign-up needed to play. Then take on real fans in ranked football trivia duels.', 'Tottenham Quiz'),
  ('everton', 'Everton Quiz', 'team', 'Everton Quiz — Test Your Toffees Knowledge', 'Nil satis nisi optimum — nothing but the best is good enough. Prove you meet the standard with our free Everton quiz: {count} verified questions on Toffees history, Goodison legends and Merseyside derby drama. Instant score, no sign-up needed to play. Kick off below.', 'About this Everton FC quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Everton are one of English football’s founding giants — a club with more top-flight seasons than almost anyone, nine league championships, and a history that starts with the birth of the Football League itself in 1888. This everton fc quiz digs into all of it."},{"id":"paragraph-2","type":"paragraph","text":"Expect questions on Dixie Dean, whose 60 league goals in a single season may never be matched; Howard Kendall’s brilliant mid-80s side that won two titles and the European Cup Winners’ Cup; goalkeeping great Neville Southall; and the teenage Wayne Rooney moment that made the whole country sit up. Every question is drawn from QuizBall’s verified trivia bank — {count} per round, split into five easy, five medium and five hard."},{"id":"paragraph-3","type":"paragraph","text":"Play free above, no account needed, and get your score instantly. Anything less than a strong showing? Nothing but the best is good enough — replay for a fresh set, or sign up free and test your Toffees knowledge in live ranked duels against real fans, where every correct answer counts like a goal."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Nothing but the best is good enough — prove your Everton knowledge in live duels.', 'Play Ranked', 'everton-v2.webp', 'Everton FC category artwork', 'Everton Quiz — Test Your Toffees Knowledge | QuizBall', 'Free Everton quiz — {count} verified questions on the Toffees. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Everton Quiz'),
  ('premier-league', 'Premier League Quiz', 'league', 'Premier League Football Quiz', 'Three decades of drama, one quiz. Play our free Premier League football quiz — {count} verified questions covering title races, record-breakers, great escapes and 5000-1 miracles. No sign-up needed: answer, get your score instantly, and see how your PL knowledge stacks up against thousands of fans.', 'About this Premier League quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Since 1992, the Premier League has produced more storylines than any competition in football: Blackburn’s 1995 title built on Shearer’s goals, Arsenal’s Invincibles going 38 games unbeaten, Agüerooooo in 93:20, Leicester defying 5000-1 odds, and Manchester City’s centurions redefining what a title-winning season looks like."},{"id":"paragraph-2","type":"paragraph","text":"This premier league football quiz takes {count} verified questions per round from QuizBall’s trivia bank — records, title races, iconic goals and the pub-quiz staples every fan should know, with a few curveballs for the anoraks. Every fact is checked, so if a question costs you a point, it’ll hold up when you double-check it."},{"id":"paragraph-3","type":"paragraph","text":"Play free above — no account needed, instant score, replay for a fresh set. When you’re warmed up, take it where it actually counts: sign up free and play ranked head-to-head trivia duels against real fans. Control possession by answering correctly, score goals, climb the leaderboard — QuizBall turns your Premier League knowledge into match results."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Think your PL knowledge is title-winning? Prove it against real fans in ranked duels.', 'Play Ranked', 'premier-league-v2.webp', 'Premier League category artwork', 'Premier League Football Quiz — Play Free | QuizBall', 'Free Premier League football quiz — {count} verified questions on 30+ years of PL history. Instant score, no sign-up to play. Beat real fans in ranked duels.', 'Premier League Quiz'),
  ('guess-the-player', 'Guess the Player', 'quiz_type', 'Guess the Player — Football Guess Who', 'Football guess who, done properly. We give you the clues — nationality, clubs, iconic moments — you name the player. {count} rounds, verified facts, instant score, and no sign-up needed to play. Get them all and you’ve earned the right to call yourself a ball-knowledge merchant.', 'About football guess who', '[{"id":"paragraph-1","type":"paragraph","text":"Guess who football stars from their story — it’s the purest test of ball knowledge there is. No badges, no kits, just facts: where they were born, where they played, what they won, and the moments that made them famous."},{"id":"paragraph-2","type":"paragraph","text":"Our guess player football game gives you verified clues and four names to choose from. {count} rounds per game, drawn from QuizBall’s bank of checked football trivia covering legends and current stars alike — from Zidane’s genius and Messi’s Ballon d’Or collection to Haaland’s record-breaking arrival in England. The clues start generous; the wrong options are designed to make you think twice."},{"id":"paragraph-3","type":"paragraph","text":"Play free above with no account — your score appears instantly, and every replay pulls a fresh set of players. Reckon you can read a career faster than your mates? Sign up free and take the player guesser format into live ranked duels, where the quickest correct answer wins possession and your knowledge turns into goals."}]'::jsonb, 'You guessed {score}/{total} — sign up free to save your score and take the guesser into ranked duels.', 'Read careers like a scout? Prove it against real fans in live trivia duels.', 'Play Ranked', 'guess-the-player-v2.webp', 'Guess the Player category artwork', 'Guess the Player — Football Guess Who Quiz | QuizBall', 'Play football guess who free — read the clues, guess the player in {count} rounds. Instant score, no sign-up to play. Then beat real fans in ranked duels.', 'Guess the Player'),
  ('career-path', 'Career Path Quiz', 'quiz_type', 'Football Career Path Quiz', 'Club by club, transfer by transfer — can you name the player from their career path alone? {count} verified transfer trails, from academy to final destination. Free to play, instant score, no sign-up needed. The ultimate guess-the-career-path challenge for proper football anoraks.', 'About the career path challenge', '[{"id":"paragraph-1","type":"paragraph","text":"A career path tells a story: the small club that spotted them, the transfer that made headlines, the late-career twist nobody predicted. This football career path quiz gives you the trail — you name the player."},{"id":"paragraph-2","type":"paragraph","text":"Every round shows a real transfer history, verified against QuizBall’s trivia bank, with four candidate names. Some paths give themselves away with one glance (there’s only one man whose journey runs through nine clubs and two spells at Milan). Others hinge on remembering where a superstar actually started — the Groningen years before Anfield, the Auxerre years before Old Trafford."},{"id":"paragraph-3","type":"paragraph","text":"You get {count} trails per round, free, no account needed, with your score shown instantly. Replay for a fresh set — the pool spans Premier League icons, world champions and cult heroes. And when you can read transfer trails like a sporting director, sign up free and bring that knowledge to ranked duels: live head-to-head trivia where the faster correct answer wins possession and puts you closer to goal."}]'::jsonb, 'You read {score}/{total} careers correctly — sign up free to save your score and defend it in a ranked duel.', 'Know every transfer since the 90s? Put it on the line in live duels against real fans.', 'Play Ranked', 'career-path-v2.webp', 'Football Career Path category artwork', 'Football Career Path Quiz — Guess the Player | QuizBall', 'Guess the player from their career path — free quiz, {count} verified transfer trails. Instant score, no sign-up to play. Then beat real fans in ranked duels.', 'Career Path Quiz'),
  ('club-badges', 'Club Badges Quiz', 'quiz_type', 'Football Club Badges Quiz — Guess the Logo', 'Every crest tells a story — liver birds, cockerels, cannons and towers. Our free football club badges quiz tests whether you can match the symbol to the club. {count} verified questions, instant score, no sign-up needed to play. How well do you really know your logos?', 'About this football logo quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Club badges are football’s oldest storytelling: Liverpool’s liver bird lifted from the city’s coat of arms, Tottenham’s cockerel perched on a ball since the days of Harry Hotspur, Manchester City’s ship honouring the Manchester Ship Canal, and Everton’s crest built around Prince Rupert’s Tower — a real 18th-century lock-up that still stands today."},{"id":"paragraph-2","type":"paragraph","text":"This football club badges quiz asks you to match the symbol to the club: {count} verified questions per round, mixing Premier League giants with historic clubs whose crests any self-respecting fan should recognise. It’s harder than it sounds — plenty of lions, birds and castles to confuse the casuals."},{"id":"paragraph-3","type":"paragraph","text":"Play the football logo quiz free above, no account needed, and get your score instantly. Replay for a fresh set of badges from our larger pool. Once you can tell your seahorses from your hammers, sign up free and test that eye in live ranked duels against real fans — where every correct answer counts like a goal."}]'::jsonb, 'You recognised {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Know every crest in the country? Prove it against real fans in live duels.', 'Play Ranked', 'badges-and-logos-v2.webp', 'Football badges and logos category artwork', 'Football Club Badges Quiz — Guess the Logo | QuizBall', 'Free football club badges quiz — guess the club from its crest. {count} verified questions, instant score, no sign-up to play. Beat real fans in duels.', 'Club Badges Quiz'),
  ('arsenal', 'Arsenal Quiz', 'team', 'Arsenal Quiz — Test Your Gunners Knowledge', 'Invincibles, Highbury heroes and north London bragging rights — how much do you really know? Play our free Arsenal quiz: verified questions covering Gunners history from Woolwich to the Emirates. No sign-up needed — answer, get your score instantly, and see how you rank against thousands of fans.', 'About this Arsenal FC quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Arsenal’s story runs from a munitions workers’ team in Woolwich to one of the most decorated clubs in England: 13 league titles, a record haul of FA Cups, and the only side of the modern era to go a whole top-flight season unbeaten — the Invincibles of 2003–04."},{"id":"paragraph-2","type":"paragraph","text":"This arsenal quiz pulls verified questions from QuizBall’s football trivia bank: Herbert Chapman’s pioneers, the 1989 Anfield miracle, Wenger’s revolution, Thierry Henry’s records and the marble halls of Highbury. Mixed difficulty — some questions any Gooner will get, a few that will separate the North Bank regulars from the tourists."},{"id":"paragraph-3","type":"paragraph","text":"Play free above, no account needed, and see your score instantly; replay for a fresh set from our Arsenal pool. Then take it further: sign up free and defend your score in live ranked duels against real fans — every correct answer keeps possession, every run of them puts the ball in the net."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Proper Gooner or just passing through? Prove it against real fans in live trivia duels.', 'Play Ranked', 'arsenal-v2.webp', 'Arsenal category artwork — red and white football theme', 'Arsenal Quiz — Test Your Gunners Knowledge | QuizBall', 'Free Arsenal quiz — verified questions on the Gunners. Instant score, no sign-up needed to play. Then take on real fans in ranked football duels.', 'Arsenal Quiz'),
  ('aston-villa', 'Aston Villa Quiz', 'team', 'Aston Villa Quiz — Test Your Villans Knowledge', 'European champions, founder members, claret and blue royalty. Play our free Aston Villa quiz — verified questions on Villans history from the Holte End to Rotterdam 1982. No sign-up needed: answer, get your score instantly, and see how you rank against thousands of football fans.', 'About this Aston Villa quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Aston Villa’s trophy cabinet was full before most clubs existed: seven league titles, seven FA Cups, and — on one immortal night in Rotterdam in 1982 — the European Cup, won by a side of homegrown grafters against mighty Bayern Munich. Peter Withe’s shin will never be forgotten in B6."},{"id":"paragraph-2","type":"paragraph","text":"This aston villa quiz pulls verified questions from QuizBall’s trivia bank across the claret-and-blue story: founder members of the Football League, the Holte End’s roar, Grealish the local heartbeat, and Emery’s revival that put Villa back among Europe’s elite."},{"id":"paragraph-3","type":"paragraph","text":"Play free above — no account needed, instant score, fresh questions from the Villa pool each replay. Then take it up a level: sign up free and play live ranked duels against real fans, where correct answers keep possession and streaks finish like Withe at the far post."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Holte Ender at heart? Prove your Villa knowledge against real fans in live duels.', 'Play Ranked', 'aston-villa-v2.webp', 'Aston Villa category artwork — claret and blue football theme', 'Aston Villa Quiz — Test Your Villans Knowledge | QuizBall', 'Free Aston Villa quiz — verified questions on the Villans. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Aston Villa Quiz'),
  ('bournemouth', 'Bournemouth Quiz', 'team', 'Bournemouth Quiz — Test Your Cherries Knowledge', 'From the brink of extinction to the Premier League — few climbs compare. Play our free Bournemouth quiz: verified questions on the Cherries, Dean Court dramas and the great escape years. No sign-up needed — instant score, then see how you compare with thousands of fans.', 'About this AFC Bournemouth quiz', '[{"id":"paragraph-1","type":"paragraph","text":"In 2008 Bournemouth were minutes from going out of business, docked points in League Two and staring at non-league football. Seven years later Eddie Howe walked them into the Premier League. English football rarely writes a better arc."},{"id":"paragraph-2","type":"paragraph","text":"This bournemouth quiz pulls verified questions from QuizBall’s trivia bank: the great escape season, promotion in 2015, the tightest ground in the top flight, red-and-black stripes borrowed from Milan, and the Iraola era that turned the Cherries into everyone’s second-favourite watch."},{"id":"paragraph-3","type":"paragraph","text":"Play free above — no account needed, your score appears instantly, and every replay brings fresh questions from the Bournemouth pool. Then test it where it counts: sign up free and play live ranked duels against real fans, where sharp answers win possession and streaks turn into goals."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'South-coast scholar? Prove your Cherries knowledge against real fans in live duels.', 'Play Ranked', 'bournemouth-v2.webp', 'AFC Bournemouth category artwork — red and black striped football theme', 'Bournemouth Quiz — Test Your Cherries Knowledge | QuizBall', 'Free AFC Bournemouth quiz — verified questions on the Cherries. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Bournemouth Quiz'),
  ('brentford', 'Brentford Quiz', 'team', 'Brentford Quiz — Test Your Bees Knowledge', 'Data-driven, fearless and impossible to ignore — Brentford rewrote the rules of getting to the top. Play our free Brentford quiz: verified questions on the Bees, from Griffin Park folklore to Premier League scalps. No sign-up needed — instant score, then compare with thousands of fans.', 'About this Brentford FC quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Brentford are modern football’s favourite underdog story: a west London club that sold its beloved Griffin Park — pub on every corner and all — bet everything on data, and beat the odds to end 74 years outside the top flight in 2021. Then they beat Arsenal on opening night for good measure."},{"id":"paragraph-2","type":"paragraph","text":"This brentford quiz pulls verified questions from QuizBall’s trivia bank: the play-off final win over Swansea, Thomas Frank’s rise, Ivan Toney’s penalties, and the moneyball model that made bigger clubs copy their homework."},{"id":"paragraph-3","type":"paragraph","text":"Play free above — no account needed, instant score, fresh questions each replay. Feeling brave? Sign up free and take your Bees knowledge into live ranked duels against real fans, where the quickest correct answer wins possession and every streak stings like, well, you know."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Know the Bees better than the data department? Prove it in live duels.', 'Play Ranked', 'brentford-v2.webp', 'Brentford category artwork — red and white striped football theme', 'Brentford Quiz — Test Your Bees Knowledge | QuizBall', 'Free Brentford quiz — verified questions on the Bees. Instant score, no sign-up needed to play. Then take on real fans in ranked football trivia duels.', 'Brentford Quiz'),
  ('brighton', 'Brighton Quiz', 'team', 'Brighton Quiz — Test Your Seagulls Knowledge', 'From nearly dropping out of the league in 1997 to European football — Brighton did it the smart way. Play our free Brighton quiz: verified questions on Seagulls history, Amex era heroes and famous escapes. No sign-up needed — instant score, then compare with thousands of fans.', 'About this Brighton & Hove Albion quiz', '[{"id":"paragraph-1","type":"paragraph","text":"In 1997 Brighton needed a final-day draw at Hereford just to stay in the Football League, homeless after the Goldstone Ground was sold from under them. Twenty-six years later they were beating Ajax in the Europa League. No club better embodies football’s long game."},{"id":"paragraph-2","type":"paragraph","text":"This brighton quiz takes verified questions from QuizBall’s trivia bank across the journey: the 1983 FA Cup final and the miss that haunts (“and Smith must score…”), Tony Bloom’s algorithmic empire, Mitoma’s thesis-approved dribbling, and the record-breaking sales that keep funding the rise."},{"id":"paragraph-3","type":"paragraph","text":"Play the bhafc quiz free above — no account needed, instant score, fresh questions each replay. Then sign up free and take your Seagulls knowledge into live ranked duels against real fans — where quick correct answers win possession, and unlike 1983, you get to take the chance again."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Smarter than the algorithm? Prove your Albion knowledge in live duels.', 'Play Ranked', 'brighton-v2.webp', 'Brighton & Hove Albion category artwork — blue and white striped football theme', 'Brighton Quiz — Test Your Seagulls Knowledge | QuizBall', 'Free Brighton quiz — verified questions on the Seagulls. Instant score, no sign-up needed to play. Then take on real fans in ranked football duels.', 'Brighton Quiz'),
  ('chelsea', 'Chelsea Quiz', 'team', 'Chelsea Quiz — Test Your Blues Knowledge', 'From Munich 2012 to Porto 2021, Stamford Bridge has seen it all. Play our free Chelsea quiz — verified questions on Blues legends, European nights and title-winning sides. No sign-up needed: instant score, then see how your Chelsea knowledge compares with thousands of football fans.', 'About this Chelsea FC quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Chelsea packed a century of history into two remarkable decades: the Abramovich takeover of 2003, Mourinho’s back-to-back titles, that rain-soaked night in Munich when Didier Drogba dragged the Blues to a first European Cup, and a second one in Porto in 2021."},{"id":"paragraph-2","type":"paragraph","text":"This chelsea quiz draws verified questions from QuizBall’s trivia bank across all of it — Zola’s magic, Lampard’s goals from midfield, Terry’s leadership, and the older history the pub experts forget: Chelsea were champions in 1955, half a century before the Special One arrived."},{"id":"paragraph-3","type":"paragraph","text":"Play free above with no account and get your score instantly; replay for a fresh set from our Chelsea pool. When a solo score stops being enough, sign up free and take your Blues knowledge into live ranked duels against real fans — correct answers win possession, streaks score goals, and the leaderboard doesn’t care about reputations."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Think you bleed blue? Prove it against real fans in live trivia duels.', 'Play Ranked', 'chelsea-v2.webp', 'Chelsea category artwork — royal blue football theme', 'Chelsea Quiz — Test Your Blues Knowledge | QuizBall', 'Free Chelsea quiz — verified questions on the Blues. Instant score, no sign-up needed to play. Then take on real fans in ranked football duels.', 'Chelsea Quiz'),
  ('coventry-city', 'Coventry City Quiz', 'team', 'Coventry City Quiz — Test Your Sky Blues Knowledge', 'Wembley 1987, the Sky Blue Revolution and three decades of top-flight graft. Play our free Coventry City quiz — verified questions on Sky Blues history from Highfield Road to today. No sign-up needed: instant score, then see how you rank against thousands of fans.', 'About this Coventry City quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Every football romantic has a soft spot for Coventry City: Jimmy Hill’s Sky Blue Revolution dragged the club into the modern age, thirty-four straight seasons of top-flight football followed, and in 1987 the Sky Blues produced one of Wembley’s great FA Cup finals — Keith Houchen flying through the air to help sink Spurs 3–2."},{"id":"paragraph-2","type":"paragraph","text":"This coventry city quiz draws verified questions from QuizBall’s trivia bank across the whole story: Highfield Road, the great escapes of the 90s, the wilderness years, and the Mark Robins rebuild that took Coventry within a penalty shoot-out of the Premier League in 2023."},{"id":"paragraph-3","type":"paragraph","text":"Play free above — no account needed, instant score, fresh questions each replay. Then sign up free and take your Sky Blues knowledge into live ranked duels against real fans, where every correct answer keeps the ball and streaks finish like Houchen."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Sky Blue through and through? Prove it against real fans in live trivia duels.', 'Play Ranked', 'coventry-city-v2.webp', 'Coventry City category artwork — sky blue football theme', 'Coventry City Quiz — Test Your Sky Blues Knowledge | QuizBall', 'Free Coventry City quiz — verified questions on the Sky Blues. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Coventry City Quiz'),
  ('crystal-palace', 'Crystal Palace Quiz', 'team', 'Crystal Palace Quiz — Test Your Eagles Knowledge', 'South London, loud and proud — and finally with silverware to match. Play our free Crystal Palace quiz: verified questions on Eagles history, Selhurst Park heroes and the Wembley day that changed everything. No sign-up needed — instant score, then see how you rank against thousands of fans.', 'About this Crystal Palace quiz', '[{"id":"paragraph-1","type":"paragraph","text":"For decades Crystal Palace were English football’s great nearly-club: the 1990 FA Cup final that needed a replay, Ian Wright’s fairytale rise from non-league, Zaha carrying the badge through thick and thin, and Selhurst Park’s Holmesdale end making more noise than grounds twice its size. Then came Wembley 2025 — Eberechi Eze, one goal, and the club’s first major trophy."},{"id":"paragraph-2","type":"paragraph","text":"This crystal palace quiz pulls verified questions from QuizBall’s trivia bank across the red-and-blue story: play-off drama, great escapes, the M23 rivalry with Brighton and the cult heroes in between."},{"id":"paragraph-3","type":"paragraph","text":"Play the cpfc quiz free above — no account needed, instant score, fresh questions from the Palace pool on every replay. Then sign up free and take your Eagles knowledge into live ranked duels against real fans, where correct answers win possession and streaks soar."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'South London and proud? Prove your Palace knowledge in live duels.', 'Play Ranked', 'crystal-palace-v2.webp', 'Crystal Palace category artwork — red and blue striped football theme', 'Crystal Palace Quiz — Test Your Eagles Knowledge | QuizBall', 'Free Crystal Palace quiz — verified questions on the Eagles. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Crystal Palace Quiz'),
  ('fulham', 'Fulham Quiz', 'team', 'Fulham Quiz — Test Your Cottagers Knowledge', 'Football by the Thames since 1879 — London’s oldest professional club has stories most can’t match. Play our free Fulham quiz: verified questions on Craven Cottage, European adventures and Cottagers cult heroes. No sign-up needed — instant score, then compare with thousands of football fans.', 'About this Fulham FC quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Fulham are London’s oldest professional club, playing by the Thames at Craven Cottage since 1896 — a ground so distinctive it has an actual cottage in the corner. Johnny Haynes made history here as the first £100-a-week footballer; decades later, Roy Hodgson’s unfancied side beat Juventus and Shakhtar on the road to a European final."},{"id":"paragraph-2","type":"paragraph","text":"This fulham quiz pulls verified questions from QuizBall’s trivia bank across the lot: the great 2010 Europa League run, Dempsey’s chip, Al-Fayed’s eccentric reign (Michael Jackson statue included), and the west London identity that makes the Cottage unlike anywhere in football."},{"id":"paragraph-3","type":"paragraph","text":"Play free above — no account needed, instant score, fresh questions on every replay. Then sign up free and take your Cottagers knowledge into live ranked duels against real fans — quick correct answers win possession, streaks turn into goals."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Riverside regular? Prove your Fulham knowledge against real fans in live duels.', 'Play Ranked', 'fulham-v2.webp', 'Fulham category artwork — white and black football theme by the Thames', 'Fulham Quiz — Test Your Cottagers Knowledge | QuizBall', 'Free Fulham quiz — verified questions on the Cottagers. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Fulham Quiz'),
  ('hull-city', 'Hull City Quiz', 'team', 'Hull City Quiz — Test Your Tigers Knowledge', 'Amber, black and built on graft — the Tigers’ story has more twists than most. Play our free Hull City quiz: verified questions from Boothferry Park days to Wembley heartbreak and Premier League firsts. No sign-up needed — instant score, then compare with thousands of fans.', 'About this Hull City quiz', '[{"id":"paragraph-1","type":"paragraph","text":"It took Hull City 104 years to reach the top flight — and when it finally happened in 2008, it arrived via one of Wembley’s most romantic moments: local lad Dean Windass, 39 years old, thumping a volley past Bristol City. The Tigers have specialised in drama ever since, from Phil Brown’s on-pitch team talk to a two-goal FA Cup final lead that slipped away against Arsenal in 2014."},{"id":"paragraph-2","type":"paragraph","text":"This hull city quiz takes verified questions from QuizBall’s trivia bank across it all: Boothferry Park nostalgia, amber-and-black icons, Steve Bruce’s promotions and the quirks that make Hull unlike anywhere else — starting with a city that’s formally called Kingston upon Hull."},{"id":"paragraph-3","type":"paragraph","text":"Play free above — no account, instant score, fresh questions every replay. Then sign up free and defend your score in live ranked duels against real fans."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Roar louder than the KC faithful? Prove your Tigers knowledge in live duels.', 'Play Ranked', 'hull-city-v2.webp', 'Hull City category artwork — amber and black football theme', 'Hull City Quiz — Test Your Tigers Knowledge | QuizBall', 'Free Hull City quiz — verified questions on the Tigers. Instant score, no sign-up needed to play. Then beat real fans in ranked football trivia duels.', 'Hull City Quiz'),
  ('ipswich-town', 'Ipswich Town Quiz', 'team', 'Ipswich Town Quiz — Test Your Tractor Boys Knowledge', 'Champions under Ramsey, European winners under Robson, and the great back-to-back rise of the 2020s. Play our free Ipswich Town quiz — verified questions on Tractor Boys history from Portman Road outwards. No sign-up needed: instant score, then see how you compare with thousands of fans.', 'About this Ipswich Town quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Portman Road has seen giants: Alf Ramsey won Ipswich the league title in 1962 before winning England the World Cup; Bobby Robson delivered the 1978 FA Cup and the 1981 UEFA Cup with John Wark scoring from everywhere. Then, four decades on, Kieran McKenna’s side went from League One to the Premier League in successive seasons — one of modern football’s great rises."},{"id":"paragraph-2","type":"paragraph","text":"This ipswich town quiz draws verified questions from QuizBall’s trivia bank across it all: the Ramsey and Robson dynasties, Suffolk pride, the Old Farm rivalry with Norwich, and the blue-shirted folklore in between."},{"id":"paragraph-3","type":"paragraph","text":"Play free above — no account needed, instant score, fresh questions from the Ipswich pool each replay. Then sign up free and take your Tractor Boys knowledge into live ranked duels against real fans, where correct answers keep possession and streaks score."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Robson-era wisdom or McKenna-era energy? Prove it in live duels.', 'Play Ranked', 'ipswich-town-v2.webp', 'Ipswich Town category artwork — blue and white football theme', 'Ipswich Town Quiz — Tractor Boys Knowledge Test | QuizBall', 'Free Ipswich Town quiz — verified questions on the Tractor Boys. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Ipswich Town Quiz'),
  ('leeds-united', 'Leeds United Quiz', 'team', 'Leeds United Quiz — Test Your Whites Knowledge', 'Revie’s machine, the last champions of the old era, Bielsa’s beautiful chaos — Leeds demand proper knowledge. Play our free Leeds United quiz: verified questions on Elland Road history and Whites folklore. No sign-up needed — instant score, then see how you rank against thousands of fans.', 'About this Leeds United quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Leeds United inspire devotion like few clubs in England. Don Revie’s side of the 60s and 70s were feared everywhere; in 1992 the Whites became the final champions of the old First Division; and between David O’Leary’s Champions League semi-finalists and Bielsa’s all-running revolutionaries, Elland Road has never done quiet."},{"id":"paragraph-2","type":"paragraph","text":"This leeds united quiz draws verified questions from QuizBall’s trivia bank across the whole saga: Bremner’s statue, the Cantona sale that still stings, Radebe the Chief, the wilderness years and the triumphant returns — most recently under Daniel Farke in 2025."},{"id":"paragraph-3","type":"paragraph","text":"Play the lufc quiz free above — no account needed, instant score, fresh questions each replay. Then sign up free and march on together into live ranked duels against real fans, where correct answers win possession and streaks turn into goals."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Marching on together? Prove your Leeds knowledge against real fans in live duels.', 'Play Ranked', 'leeds-united-v2.webp', 'Leeds United category artwork — white and yellow football theme', 'Leeds United Quiz — Test Your Whites Knowledge | QuizBall', 'Free Leeds United quiz — verified questions on the Whites. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Leeds United Quiz'),
  ('manchester-city', 'Manchester City Quiz', 'team', 'Manchester City Quiz — Test Your City Knowledge', '93:20. If those numbers mean something to you, this is your quiz. Play our free Manchester City quiz — verified questions from Maine Road memories to treble winners and title streaks. No sign-up needed: instant score, then see how you rank against thousands of football fans.', 'About this Manchester City quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Few clubs have lived both extremes like Manchester City: third-tier football at Maine Road in 1999, then the Agüero moment, the Centurions, four titles in a row and a 2023 treble. It’s a history built for trivia."},{"id":"paragraph-2","type":"paragraph","text":"This manchester city quiz takes verified questions from QuizBall’s football bank across the whole arc — the takeover that changed everything in 2008, Silva and De Bruyne pulling the strings, Haaland rewriting the scoring records, and the older, scrappier decades that true Blues never let anyone forget."},{"id":"paragraph-3","type":"paragraph","text":"Play the man city quiz free above — no account, instant score, fresh questions on every replay. Then put it on the line: sign up free and play live ranked duels against real fans, where quick correct answers win possession and knowledge turns into goals. The leaderboard has room for one more perfectionist."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Centurion-level knowledge? Prove it against real fans in live trivia duels.', 'Play Ranked', 'manchester-city-v2.webp', 'Manchester City category artwork — sky blue football theme', 'Manchester City Quiz — Test Your City Knowledge | QuizBall', 'Free Manchester City quiz — verified questions on the Citizens. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Manchester City Quiz'),
  ('newcastle-united', 'Newcastle United Quiz', 'team', 'Newcastle United Quiz — Test Your Magpies Knowledge', 'St James’ Park, the Entertainers, and a trophy drought that finally ended — Newcastle’s story demands proper knowledge. Play our free Newcastle United quiz: verified questions on Magpies legends, Keegan drama and Wembley glory. No sign-up needed — instant score, then compare with thousands of fans.', 'About this Newcastle United quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Few clubs feel football like Newcastle. Fifty-two thousand pack St James’ Park through every era — the Milburn years, Keegan’s Entertainers throwing away a twelve-point lead in the most dramatic title race of the Premier League age, Shearer’s 206 goals, and finally, in 2025, a Wembley day that ended seven decades without a domestic trophy."},{"id":"paragraph-2","type":"paragraph","text":"This newcastle united quiz draws verified questions from QuizBall’s trivia bank across the lot: the 1969 Fairs Cup, Sir Bobby Robson’s redemption years, the 2021 takeover, and the black-and-white folklore every Geordie inherits at birth."},{"id":"paragraph-3","type":"paragraph","text":"Play the nufc quiz free above — no account needed, instant score, fresh questions on every replay. Then sign up free and take your Toon knowledge into live ranked duels against real fans, where quick correct answers win possession and streaks hit like a Shearer volley."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Howay man — prove your Toon knowledge against real fans in live duels.', 'Play Ranked', 'newcastle-united-v2.webp', 'Newcastle United category artwork — black and white striped football theme', 'Newcastle United Quiz — Magpies Knowledge Test | QuizBall', 'Free Newcastle United quiz — verified questions on the Magpies. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Newcastle United Quiz'),
  ('nottingham-forest', 'Nottingham Forest Quiz', 'team', 'Nottingham Forest Quiz — Test Your Reds Knowledge', 'Two European Cups. Back to back. From a provincial city on the Trent — it will never happen again. Play our free Nottingham Forest quiz: verified questions on Clough’s miracle men and everything since. No sign-up needed — instant score, then compare with thousands of football fans.', 'About this Nottingham Forest quiz', '[{"id":"paragraph-1","type":"paragraph","text":"No story in football matches it: Brian Clough and Peter Taylor took a second-tier Nottingham Forest, won promotion, won the league at the first attempt, then conquered Europe twice in a row — 1979 and 1980 — with John Robertson jinking down the wing and the first million-pound footballer heading in at Munich."},{"id":"paragraph-2","type":"paragraph","text":"This nottingham forest quiz draws verified questions from QuizBall’s trivia bank across the Garibaldi-red story: the miracle years, Psycho Pearce and Des Walker, the Premier League returns, and a City Ground that still hums with what happened under Old Big ’Ead."},{"id":"paragraph-3","type":"paragraph","text":"Play free above — no account needed, your score appears instantly, and each replay pulls fresh questions from the Forest pool. Then sign up free and take that knowledge into live ranked duels against real fans — correct answers win possession, streaks finish like Robertson in Madrid."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Clough-level standards? Prove your Forest knowledge against real fans in live duels.', 'Play Ranked', 'nottingham-forest-v2.webp', 'Nottingham Forest category artwork — Garibaldi red football theme', 'Nottingham Forest Quiz — Test Your Reds Knowledge | QuizBall', 'Free Nottingham Forest quiz — verified questions on Forest. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Nottingham Forest Quiz'),
  ('sunderland', 'Sunderland Quiz', 'team', 'Sunderland Quiz — Test Your Black Cats Knowledge', 'The Stadium of Light, the miracle of 1973 and a fanbase that never stops. Play our free Sunderland quiz — verified questions on Black Cats history, Wearside heroes and Wembley shocks. No sign-up needed: instant score, then see how you rank against thousands of fans.', 'About this Sunderland AFC quiz', '[{"id":"paragraph-1","type":"paragraph","text":"Sunderland supporters have seen everything: six league titles in the club’s early pomp, the 1973 miracle when a Second Division side beat mighty Leeds at Wembley, thirty-goal seasons from Kevin Phillips, two Netflix series’ worth of heartbreak — and then a Wembley play-off day in 2025 that finally went right."},{"id":"paragraph-2","type":"paragraph","text":"This sunderland quiz pulls verified questions from QuizBall’s trivia bank across all of it: Roker Park’s roar, Montgomery’s double save, Quinn and Phillips, the Tyne–Wear rivalry and the red-and-white stripes that mean everything on Wearside."},{"id":"paragraph-3","type":"paragraph","text":"Play free above — no account needed, your score appears instantly, and every replay brings fresh questions from the Sunderland pool. Then do what Black Cats fans do best — turn up and fight: sign up free and play live ranked duels against real fans, where correct answers win possession and streaks turn into goals."}]'::jsonb, 'You scored {score}/{total} — sign up free to save your score and defend it in a ranked duel.', 'Haway — prove your Black Cats knowledge against real fans in live duels.', 'Play Ranked', 'sunderland-v2.webp', 'Sunderland category artwork — red and white striped football theme', 'Sunderland Quiz — Test Your Black Cats Knowledge | QuizBall', 'Free Sunderland quiz — verified questions on the Black Cats. Instant score, no sign-up needed to play. Then beat real fans in ranked football duels.', 'Sunderland Quiz');

UPDATE public.campaign_quizzes quiz
SET internal_name = seed.internal_name,
    page_category = seed.page_category,
    question_set_slug = quiz.slug,
    h1 = seed.h1,
    lede = seed.lede,
    about_heading = seed.about_heading,
    about_blocks = seed.about_blocks,
    score_cta = seed.score_cta,
    footer_banner_text = seed.footer_banner_text,
    footer_button_label = seed.footer_button_label,
    hero_image_url = 'categories/' || seed.hero_image_file,
    hero_image_alt = seed.hero_image_alt,
    seo_title = seed.seo_title,
    meta_description = seed.meta_description,
    breadcrumb_label = seed.breadcrumb_label,
    locale_mode = 'en_only',
    published_at = CASE WHEN quiz.status = 'published' THEN COALESCE(quiz.published_at, NOW()) ELSE quiz.published_at END,
    updated_at = NOW()
FROM quiz_page_content_seed seed
WHERE quiz.slug = seed.slug;

DELETE FROM public.campaign_quiz_related_pages
WHERE quiz_slug IN (SELECT slug FROM quiz_page_content_seed);

